/* Interactive pedigree figures for the research page.
 *
 * Redraws a breeding design generated by tools/pedigree_to_js.py with the same
 * encoding as the original R plot: teal circles are dams, orange squares are
 * sires, both sized by brood, and every parent-offspring line keeps the colour
 * of the parent it comes from.
 *
 * Two things happen on top of the static figure. It assembles itself once on
 * scroll, one family at a time, largest brood first. After that, pointing at
 * any individual dims the rest of the network and blooms its immediate family:
 * a dam or sire lights its whole brood, an offspring lights the pair that
 * produced it.
 *
 * A panel says which dataset it wants with data-ped, so one script serves both
 * species panels on the page.
 */
(function () {
  "use strict";

  var DAM = 0, SIRE = 1, OFF = 2;
  var NS = "http://www.w3.org/2000/svg";
  var FAMILY_STEP = 45;        // ms between families during the reveal
  var AMBIENT_MS = 3400;       // how long each self-running highlight holds
  var calm = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  function el(name, attrs) {
    var node = document.createElementNS(NS, name);
    for (var key in attrs) node.setAttribute(key, attrs[key]);
    return node;
  }

  function build(host, data) {
    /* ---- adjacency ----------------------------------------------------- */
    var nodes = data.nodes;
    var links = data.links;
    var kin = nodes.map(function () { return []; });   // node -> [link index]

    links.forEach(function (link, i) {
      kin[link[0]].push(i);
      kin[link[1]].push(i);
    });

    var parents = [];
    nodes.forEach(function (n, i) { if (n[3] !== OFF) parents.push(i); });

    /* ---- reveal order --------------------------------------------------
     * Big families first, so the backbone of the design lands before the
     * stragglers fill in around it.
     */
    var order = parents.slice().sort(function (a, b) {
      return kin[b].length - kin[a].length;
    });

    var famDelay = [];                               // parent node -> ms
    var delayOf = [];                                // any node -> ms
    order.forEach(function (p, rank) { famDelay[p] = rank * FAMILY_STEP; });
    nodes.forEach(function (n, i) {
      if (n[3] !== OFF) {
        delayOf[i] = famDelay[i] + 80;
        return;
      }
      var first = Infinity;
      kin[i].forEach(function (k) {
        first = Math.min(first, famDelay[links[k][0]]);
      });
      delayOf[i] = (first === Infinity ? 0 : first) + 320;
    });
    var settleMs = order.length * FAMILY_STEP + 900;

    /* ---- draw ----------------------------------------------------------- */
    var svg = el("svg", {
      viewBox: "0 0 " + data.w + " " + data.h,
      preserveAspectRatio: "xMidYMid meet",
      class: "ped-svg",
      role: "img",
      "aria-label": host.getAttribute("data-ped-label") || "Pedigree network"
    });
    // Names and hit slack are in viewBox units, and the two designs are
    // plotted in boxes of different sizes, so both are taken as a fraction of
    // the box. That way they land at the same size on screen in either panel.
    svg.style.setProperty("--ped-label", (data.w / 40).toFixed(2) + "px");
    var hitRadius = data.w / 60;

    var edgeLayer = el("g", { class: "ped-edges" });
    var nodeLayer = el("g", { class: "ped-nodes" });
    var labelLayer = el("g", { class: "ped-labels" });

    var edgeEls = links.map(function (link) {
      var a = nodes[link[0]], b = nodes[link[1]];
      return el("line", {
        x1: a[0], y1: a[1], x2: b[0], y2: b[1],
        class: "ped-edge " + (a[3] === DAM ? "is-dam" : "is-sire")
      });
    });

    // One group per family, pinned to its parent, so the reveal grows outward
    // from each parent instead of every line fading in at once.
    order.forEach(function (p) {
      var group = el("g", { class: "ped-family" });
      group.style.setProperty("--d", famDelay[p] + "ms");
      group.style.transformOrigin = nodes[p][0] + "px " + nodes[p][1] + "px";
      kin[p].forEach(function (k) { group.appendChild(edgeEls[k]); });
      edgeLayer.appendChild(group);
    });

    var nodeEls = nodes.map(function (n, i) {
      var kind = n[3];
      var shape;
      if (kind === DAM) {
        shape = el("circle", { cx: n[0], cy: n[1], r: n[2] });
      } else {
        // Sires are squares, offspring the same shape at dot scale.
        var side = n[2] * 2;
        shape = el("rect", {
          x: n[0] - n[2], y: n[1] - n[2], width: side, height: side,
          rx: kind === OFF ? n[2] * 0.4 : 0
        });
      }
      shape.setAttribute("class", "ped-node " +
        (kind === DAM ? "is-dam" : kind === SIRE ? "is-sire" : "is-off"));
      // Grow from the centre rather than the top-left corner on highlight.
      shape.style.transformOrigin = n[0] + "px " + n[1] + "px";
      shape.style.setProperty("--d", delayOf[i] + "ms");
      return shape;
    });

    // Parent names sit above their shape but stay hidden until that family is
    // lit: all of them at once is the crowding the original figure suffers
    // from.
    var labelEls = [];
    parents.forEach(function (i) {
      var n = nodes[i];
      var text = el("text", {
        x: n[0], y: n[1] - n[2] - 2.2,
        class: "ped-label", "text-anchor": "middle"
      });
      text.textContent = n[4];
      labelEls[i] = text;
      labelLayer.appendChild(text);
    });

    nodeEls.forEach(function (e) { nodeLayer.appendChild(e); });
    svg.appendChild(edgeLayer);
    svg.appendChild(nodeLayer);
    svg.appendChild(labelLayer);
    host.appendChild(svg);

    var chip = document.createElement("span");
    chip.className = "ped-chip";
    chip.setAttribute("aria-hidden", "true");
    host.appendChild(chip);

    /* ---- highlight ------------------------------------------------------ */
    var lit = [];
    var current = -1;

    function clear() {
      lit.forEach(function (e) { e.classList.remove("is-lit"); });
      lit = [];
      current = -1;
      host.classList.remove("is-focused");
      chip.classList.remove("is-on");
    }

    function describe(index) {
      var n = nodes[index];
      if (n[3] !== OFF) {
        var brood = kin[index].length;
        return "<b>" + n[4] + "</b>" + (n[3] === DAM ? " dam" : " sire")
          + " · " + brood + " offspring";
      }
      var names = kin[index].map(function (i) { return nodes[links[i][0]][4]; });
      return names.length === 2
        ? "offspring · <b>" + names[0] + "</b> × <b>" + names[1] + "</b>"
        : "offspring · <b>" + (names[0] || "?") + "</b>";
    }

    function light(index, pointer) {
      if (index === current) return;
      clear();
      current = index;

      lit.push(nodeEls[index]);
      if (labelEls[index]) lit.push(labelEls[index]);
      kin[index].forEach(function (i) {
        lit.push(edgeEls[i]);
        var other = links[i][0] === index ? links[i][1] : links[i][0];
        lit.push(nodeEls[other]);
        if (labelEls[other]) lit.push(labelEls[other]);
      });
      lit.forEach(function (e) { e.classList.add("is-lit"); });
      host.classList.add("is-focused");

      chip.innerHTML = describe(index);
      var box = host.getBoundingClientRect();
      var at = pointer || toClient(index);
      chip.style.left =
        Math.min(Math.max(at.x - box.left, 8), box.width - 8) + "px";

      // Under the pointer the chip rides just above the cursor. On the ambient
      // cycle it drops below the shape instead, leaving the name label above
      // it clear.
      chip.classList.toggle("is-below", !pointer);
      var y = pointer
        ? Math.min(Math.max(at.y - box.top - 14, 8), box.height - 8)
        : Math.min(at.y - box.top + scale() * nodes[index][2] + 8,
                   box.height - 26);
      chip.style.top = y + "px";
      chip.classList.add("is-on");
    }

    /* ---- coordinates ---------------------------------------------------
     * getScreenCTM is the SVG's own viewBox-to-screen mapping, so the maths
     * stays correct whatever preserveAspectRatio or panel size is in play.
     */
    function toView(clientX, clientY) {
      var ctm = svg.getScreenCTM();
      if (!ctm) return null;
      var pt = svg.createSVGPoint();
      pt.x = clientX;
      pt.y = clientY;
      return pt.matrixTransform(ctm.inverse());
    }

    function scale() {                     // viewBox units -> screen pixels
      var ctm = svg.getScreenCTM();
      return ctm ? ctm.a : 1;
    }

    function toClient(index) {
      var ctm = svg.getScreenCTM();
      var pt = svg.createSVGPoint();
      pt.x = nodes[index][0];
      pt.y = nodes[index][1];
      pt = ctm ? pt.matrixTransform(ctm) : pt;
      return { x: pt.x, y: pt.y };
    }

    /* ---- pointer picking -----------------------------------------------
     * Nearly every node is barely a pixel wide, so instead of per-element hit
     * targets we take the pointer position and ask which individual it is
     * closest to, letting the labelled parents win ties by their real radius.
     */
    function pick(event) {
      var at = toView(event.clientX, event.clientY);
      if (!at) return -1;
      var x = at.x, y = at.y;

      var best = -1, bestGap = Infinity;
      for (var i = 0; i < nodes.length; i++) {
        var n = nodes[i];
        var gap = Math.hypot(n[0] - x, n[1] - y) - Math.max(n[2], hitRadius);
        if (gap < bestGap) { bestGap = gap; best = i; }
      }
      return bestGap <= 0 ? best : -1;
    }

    host.addEventListener("pointermove", function (event) {
      stopAmbient();
      var hit = pick(event);
      if (hit < 0) clear();
      else light(hit, { x: event.clientX, y: event.clientY });
    });
    host.addEventListener("pointerleave", clear);
    host.addEventListener("pointerdown", function (event) {
      stopAmbient();
      var hit = pick(event);
      // Touch gets no pointerleave, so a tap on empty space is the way out.
      if (hit < 0) clear();
      else light(hit, { x: event.clientX, y: event.clientY });
    });

    /* ---- ambient cycle -------------------------------------------------
     * Nobody thinks to hover a figure, so the graph walks through families on
     * its own until someone takes over.
     */
    var timer = null;
    var stopped = false;

    function stopAmbient() {
      stopped = true;
      if (timer) { clearTimeout(timer); timer = null; }
    }

    function ambient() {
      if (stopped) return;
      light(parents[Math.floor(Math.random() * parents.length)]);
      timer = setTimeout(function () {
        if (stopped) return;
        clear();
        timer = setTimeout(ambient, AMBIENT_MS / 3);
      }, AMBIENT_MS);
    }

    /* ---- entrance ------------------------------------------------------
     * The reveal runs off CSS animations, and a filled animation would beat
     * the transforms the highlight needs, so the drawing state is torn down
     * for a plain settled one as soon as it has played out.
     */
    function settle() {
      host.classList.remove("is-drawing");
      host.classList.add("is-settled");
      if (!calm && !stopped) timer = setTimeout(ambient, 600);
    }

    var seen = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (!entry.isIntersecting) return;
        seen.disconnect();
        if (calm) { settle(); return; }
        host.classList.add("is-drawing");
        setTimeout(settle, settleMs);
      });
    }, { threshold: 0.2 });
    seen.observe(host);
  }

  /* ---- wiring ---------------------------------------------------------- */
  var panels = document.querySelectorAll("[data-ped]");
  for (var i = 0; i < panels.length; i++) {
    var data = window[panels[i].getAttribute("data-ped")];
    if (data) build(panels[i], data);
  }
})();
